verifier_source:
# Standalone exact verifier. No imports, no filesystem, no network, no printing.
# Discipline: fail closed, exact integer arithmetic, deterministic.
# verify(witness) raises on any failed check; exit 0 only if every odd n in [3,255]
# admits l with 2^l < n and n - 2^l squarefree (k >= 1 and no d >= 2 has d*d | k),
# and specifically n = 185 = 57 + 2^7 with 57 squarefree.

def is_sqf(k):
    if k <= 0:
        raise ValueError("nonpositive k")
    d = 2
    while d * d <= k:
        if k % (d * d) == 0:
            return False
        d += 1
    return True

def verify(witness):
    count = 0
    for n in range(3, 256, 2):
        count += 1
        found = False
        l = 0
        while (1 << l) < n:
            k = n - (1 << l)
            if k >= 1 and is_sqf(k):
                found = True
            l += 1
        if not found:
            raise ValueError("no decomposition for n=%d" % n)
    if count != 127:
        raise ValueError("wrong count %d" % count)
    if not (185 - 128 == 57 and is_sqf(57) and (1 << 7) == 128):
        raise ValueError("witness 185 = 57 + 2^7 failed")
    return True
